package com.oai.harmonywake; import android.app.*; import android.content.*; import java.util.*; public class AlarmScheduler { public static void schedule(Context c,WakeTask t){cancel(c,t.id);if(!t.enabled)return;Calendar n=Calendar.getInstance();n.set(Calendar.HOUR_OF_DAY,t.hour);n.set(Calendar.MINUTE,t.minute);n.set(Calendar.SECOND,0);n.set(Calendar.MILLISECOND,0);if(n.getTimeInMillis()<=System.currentTimeMillis())n.add(Calendar.DAY_OF_YEAR,1);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);Intent ri=new Intent(c,AlarmReceiver.class).putExtra("task_id",t.id);PendingIntent op=PendingIntent.getBroadcast(c,t.id,ri,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent show=PendingIntent.getActivity(c,100000+t.id,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);am.setAlarmClock(new AlarmManager.AlarmClockInfo(n.getTimeInMillis(),show),op);} public static void cancel(Context c,int id){AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent p=PendingIntent.getBroadcast(c,id,new Intent(c,AlarmReceiver.class),PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE);if(p!=null){am.cancel(p);p.cancel();}} public static void rescheduleAll(Context c){for(WakeTask t:TaskStore.load(c))schedule(c,t);}}